import math

class Statistics3:
    ODD_DIVISOR = 2
    EVEN_DIVISOR = 2
    MIN_SAMPLE_SIZE = 2
    ZERO_DIVISOR = 0
    TWO = 2
    ONE = 1
    ZERO = 0

    @staticmethod
    def median(data):
        sorted_data = sorted(data)
        n = len(sorted_data)
        if n % 2 == 1:
            return sorted_data[n // 2]
        else:
            return (sorted_data[n // 2 - 1] + sorted_data[n // 2]) / 2

    @staticmethod
    def mode(data):
        counts = {}
        for value in data:
            counts[value] = counts.get(value, 0) + 1
        max_count = max(counts.values())
        mode_values = [value for value, count in counts.items() if count == max_count]
        return mode_values

    @staticmethod
    def _calculate_mean(xs):
        return sum(xs) / len(xs)

    @staticmethod
    def _calculate_numerator(x, y, mean_x, mean_y):
        return sum((xi - mean_x) * (yi - mean_y) for xi, yi in zip(x, y))

    @staticmethod
    def _calculate_denominator(x, y, mean_x, mean_y):
        sum_sq_x = sum((xi - mean_x) ** 2 for xi in x)
        sum_sq_y = sum((yi - mean_y) ** 2 for yi in y)
        return math.sqrt(sum_sq_x * sum_sq_y)

    @staticmethod
    def correlation(x, y):
        n = len(x)
        mean_x = Statistics3._calculate_mean(x)
        mean_y = Statistics3._calculate_mean(y)
        numerator = Statistics3._calculate_numerator(x, y, mean_x, mean_y)
        denominator = Statistics3._calculate_denominator(x, y, mean_x, mean_y)
        if denominator == 0:
            return None
        return numerator / denominator

    @staticmethod
    def mean(data):
        if len(data) == 0:
            return None
        return sum(data) / len(data)

    @staticmethod
    def _extract_column(data, index):
        return [row[index] for row in data]

    @staticmethod
    def correlation_matrix(data):
        num_columns = len(data[0])
        matrix = []
        for i in range(num_columns):
            row = []
            for j in range(num_columns):
                column1 = Statistics3._extract_column(data, i)
                column2 = Statistics3._extract_column(data, j)
                correlation = Statistics3.correlation(column1, column2)
                row.append(correlation)
            matrix.append(row)
        return matrix

    @staticmethod
    def _calculate_variance(data, mean_value):
        n = len(data)
        return sum((x - mean_value) ** 2 for x in data) / (n - 1)

    @staticmethod
    def standard_deviation(data):
        n = len(data)
        if n < 2:
            return None
        mean_value = Statistics3.mean(data)
        variance = Statistics3._calculate_variance(data, mean_value)
        return math.sqrt(variance)

    @staticmethod
    def z_score(data):
        mean = Statistics3.mean(data)
        std_deviation = Statistics3.standard_deviation(data)
        if std_deviation is None or std_deviation == 0:
            return None
        return [(x - mean) / std_deviation for x in data]
